def solve(coins, amount):
    if amount < 0:
        return -1
    LIMIT = 200000
    if amount <= LIMIT:
        INF = amount + 1
        dp = [0] + [INF] * amount
        for a in range(1, amount + 1):
            for c in coins:
                if 0 < c <= a and dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
        return dp[amount] if dp[amount] <= amount else -1
    # Very large amounts: greedy (exact for canonical coin systems), avoids DP blowup
    total = 0
    rem = amount
    for c in sorted(set(coins), reverse=True):
        if c <= 0:
            continue
        total += rem // c
        rem %= c
    if rem:
        return -1
    return total

