def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting algorithm with binary search, O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        # find position to insert x in tails
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
