def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* using unlimited *coins*.
    If it is not possible, return -1.
    Uses classic DP O(amount * len(coins))."""
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array with a sentinel larger than any possible count
    INF = amount + 1  # larger than max possible coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # choose coin c
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

