def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than n.
    Handles non-positive n by returning 0.
    """
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n-1
    limit = n
    is_prime = [True] * limit
    is_prime[0:2] = [False, False]
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            step = i
            start = i * i
            is_prime[start:limit:step] = [False] * ((limit - 1 - start) // step + 1)
    return sum(is_prime)

