def solve(n: int) -> int:
    """Return the count of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    sieve = bytearray(b'\x01') * n  # True for potential primes
    sieve[0:2] = b'\x00\x00'
    limit = int(n ** 0.5) + 1
    for p in range(2, limit):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:n:step] = b'\x00' * ((n - start - 1) // step + 1)
    # Count True entries
    return sum(sieve)

