def solve(matrix):
    """Return the determinant of an integer square matrix using the Bareiss algorithm.
    The Bareiss algorithm performs exact integer Gaussian elimination, avoiding fractions.
    An empty matrix (size 0) is defined to have determinant 1.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a deep copy to avoid mutating input
    A = [list(map(int, row)) for row in matrix]
    det = 1
    for k in range(n - 1):
        # Find a non-zero pivot; if zero, swap with a lower row
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det  # swapping rows changes sign
                    break
            else:
                return 0
        pivot = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update: A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // (A[k-1][k-1] if k else 1)
                prev = A[k - 1][k - 1] if k > 0 else 1
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev
            A[i][k] = 0
    det *= A[n - 1][n - 1]
    return det

